using System;using System.IO;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;using System.Collections.Generic;
namespace FleetLab {
    public sealed class FleetSetup:UserControl {
        internal readonly FleetProgram Program;internal readonly FleetCanvas Canvas=new FleetCanvas();
        internal Game Draft {get;private set;}internal int SelectedShip {get;private set;}internal Point GridCell {get;private set;}
        internal Bitmap CurrentImage {get{return image;}}internal bool HasOpened {get{return Draft!=null;}}
        internal readonly Button ShuffleButton=new Button(),BackButton=new Button();
        public event Action StartRequested,ReturnRequested;
        readonly IndexedImage card;readonly List<IndexedImage> frames;readonly ClassicShips ships;readonly FleetOverview overview;readonly Label note=new Label();Bitmap image;bool disposed;
        public FleetSetup(string assets){Dock=DockStyle.Fill;BackColor=Color.FromArgb(10,22,34);ForeColor=Color.WhiteSmoke;string graphics=Path.Combine(assets,"Graphics"),programs=Path.Combine(Path.GetDirectoryName(assets),"Programs");card=Assets.Pcx(Path.Combine(graphics,"EC_FLEET.PCX"));var reserved=ClassicPalette.Gameplay(File.ReadAllBytes(Path.Combine(graphics,"ISLAND.COL")));for(int i=0;i<256;i++)if(i<10||i>245)card.Palette[i]=reserved[i];frames=Assets.Sph(Path.Combine(graphics,"EO_FLEET.SPH"),card.Palette);Program=FleetProgram.Read(File.ReadAllBytes(Path.Combine(programs,"FleetFlow.seqbin")),File.ReadAllBytes(Path.Combine(programs,"FleetButtons.seqbin")),frames);ships=new ClassicShips(graphics,card.Palette,100);
            try {overview=new FleetOverview(graphics,card.Palette,frames);}catch {ships.Dispose();throw;}
            Canvas.Owner=this;Canvas.Dock=DockStyle.Fill;Canvas.AccessibleName="Classic fleet configuration; arrows move cursor, Enter selects or drops, Tab selects Start, Escape returns";Controls.Add(Canvas);var head=new Panel{Dock=DockStyle.Top,Height=96,Padding=new Padding(12,4,12,2)};Controls.Add(head);note.Dock=DockStyle.Fill;head.Controls.Add(note);var bar=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=39,WrapContents=false};head.Controls.Add(bar);Add(bar,ShuffleButton,"Shuffle fleet",delegate{if(Draft!=null){Draft.AutoPlace();SelectedShip=-1;Render();Canvas.Focus();}});Add(bar,BackButton,"Back to setup",delegate{Back();});SelectedShip=-1;
        }
        static void Add(Control p,Button b,string text,EventHandler action){b.Text=text;b.AutoSize=true;b.Height=32;b.BackColor=Color.FromArgb(31,56,75);b.ForeColor=Color.WhiteSmoke;b.FlatStyle=FlatStyle.Flat;b.Click+=action;p.Controls.Add(b);}
        internal void Begin(Game draft){if(disposed)return;if(draft==null||!draft.Rules.FixedY||draft.Phase!=Phase.Placement||draft.Player.Ships.Count!=5)throw new ArgumentException("Complete Classic draft required");Reset();Draft=draft;SelectedShip=-1;GridCell=draft.Player.Ships[0].Cells[draft.Player.Ships[0].Cells.Count/2];note.Text="Select a ship, then its new middle cell. Arrows + Enter also work; Tab selects Start. Fixed Classic roster. Escape cancels a move; Shuffle uses the original Classic placement algorithm.";Render();Canvas.Focus();}
        internal void Reset(){if(disposed)return;Draft=null;SelectedShip=-1;Canvas.ClearPress();var old=image;image=null;Canvas.Invalidate();if(old!=null)old.Dispose();}
        public void Pause(){if(disposed)return;Canvas.ClearPress();}
        void Back(){if(disposed)return;Pause();if(ReturnRequested!=null)ReturnRequested();}
        internal void Activate(int button){if(disposed||Draft==null)return;if(button==3){Back();return;}if(button==2&&SelectedShip<0){if(StartRequested!=null)StartRequested();return;}note.Text=button==2?"Place or cancel the selected ship before starting. Escape cancels a move.":"Classic uses a fixed five-ship roster. Purchasing, Clear and Restore are disabled.";}
        internal void Cell(Point point){if(disposed||Draft==null||!Board.Inside(point))return;GridCell=point;if(SelectedShip<0){var ship=Draft.Player.ShipAt(point);if(ship!=null)SelectedShip=Draft.Player.Ships.IndexOf(ship);}else if(Draft.MovePlacedShip(SelectedShip,point)){SelectedShip=-1;note.Text="Ship moved. Select another ship or Start Game.";}else note.Text="Invalid move: keep the whole ship inside the grid without overlap. Its old position is retained.";Render();}
        internal bool Key(Keys key){if(disposed||Draft==null)return false;if(key==Keys.Escape){if(SelectedShip>=0){SelectedShip=-1;Render();}else Back();return true;}if(key==Keys.Tab){Canvas.StartFocused=!Canvas.StartFocused;Canvas.Invalidate();return true;}if(key==Keys.Enter||key==Keys.Space){if(Canvas.StartFocused)Activate(2);else Cell(GridCell);return true;}int dx=key==Keys.Left?-1:key==Keys.Right?1:0,dy=key==Keys.Up?-1:key==Keys.Down?1:0;if(dx!=0||dy!=0){Canvas.StartFocused=false;GridCell=new Point(Math.Max(0,Math.Min(9,GridCell.X+dx)),Math.Max(0,Math.Min(9,GridCell.Y+dy)));Render();return true;}return false;}
        void Render(){if(disposed||Draft==null)return;Bitmap next=FleetProgram.Viewport(card).Bitmap();using(var g=Graphics.FromImage(next)){overview.Draw(g,Draft.Player);foreach(var ship in Draft.Player.Ships){var bmp=ships.Image(ship.SourceType);var at=FleetGeometry.Anchor(ship.Cells[0],ship.Cells.Count);g.DrawImageUnscaled(bmp,ClassicShips.Bounds(at,bmp.Size).Location);}if(SelectedShip>=0){var ship=Draft.Player.Ships[SelectedShip];bool valid=Draft.Player.CanMoveClassic(SelectedShip,GridCell);using(var fill=new SolidBrush(Color.FromArgb(105,valid?Color.Lime:Color.Red)))using(var pen=new Pen(valid?Color.Lime:Color.Red,2)){for(int i=0;i<ship.Cells.Count;i++)Polygon(g,pen,fill,new Point(GridCell.X,GridCell.Y-ship.Cells.Count/2+i));}}using(var pen=new Pen(Color.Gold,2))Polygon(g,pen,null,GridCell);}
            var old=image;image=next;Canvas.Invalidate();if(old!=null)old.Dispose();
        }
        static void Polygon(Graphics g,Pen pen,Brush fill,Point cell){var p=new[]{FleetGeometry.Project(cell.X,cell.Y),FleetGeometry.Project(cell.X+1,cell.Y),FleetGeometry.Project(cell.X+1,cell.Y+1),FleetGeometry.Project(cell.X,cell.Y+1)};if(fill!=null)g.FillPolygon(fill,p);g.DrawPolygon(pen,p);}
        protected override void Dispose(bool disposing){if(disposing&&!disposed){Reset();disposed=true;ships.Dispose();overview.Dispose();}base.Dispose(disposing);}
        internal sealed class FleetCanvas:Control {
            internal FleetSetup Owner;internal bool StartFocused;Point? pressed;int pressedButton=-1;
            public FleetCanvas(){DoubleBuffered=true;ResizeRedraw=true;TabStop=true;BackColor=Color.Black;}
            internal RectangleF Bounds4x3 {get{float scale=Math.Min(Width/640f,Height/480f);return new RectangleF((Width-640*scale)/2,(Height-480*scale)/2,640*scale,480*scale);}}
            Point? Pixel(int x,int y){var b=Bounds4x3;if(b.Width<=0||x<b.Left||y<b.Top||x>=b.Right||y>=b.Bottom)return null;return new Point((int)((x-b.X)*640/b.Width),(int)((y-b.Y)*480/b.Height));}
            internal void ClearPress(){pressed=null;pressedButton=-1;StartFocused=false;}
            protected override bool IsInputKey(Keys key){return key==Keys.Tab||key==Keys.Up||key==Keys.Down||key==Keys.Left||key==Keys.Right||base.IsInputKey(key);}
            protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button!=MouseButtons.Left||Owner.Draft==null)return;Focus();pressed=Pixel(e.X,e.Y);pressedButton=pressed.HasValue?Owner.Program.Hit(pressed.Value.X,pressed.Value.Y):-1;}
            protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);var before=pressed;int button=pressedButton;ClearPress();if(e.Button!=MouseButtons.Left||!before.HasValue)return;var p=Pixel(e.X,e.Y);if(!p.HasValue)return;if(button>=0){if(Owner.Program.Hit(p.Value.X,p.Value.Y)==button)Owner.Activate(button);}else{var cell=FleetGeometry.Pick(p.Value);var old=FleetGeometry.Pick(before.Value);if(cell.HasValue&&old==cell)Owner.Cell(cell.Value);}}
            protected override void OnMouseCaptureChanged(EventArgs e){base.OnMouseCaptureChanged(e);if(!Capture)ClearPress();}
            protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(Owner==null||Owner.image==null)return;e.Graphics.InterpolationMode=InterpolationMode.NearestNeighbor;e.Graphics.PixelOffsetMode=PixelOffsetMode.Half;var b=Bounds4x3;e.Graphics.DrawImage(Owner.image,b);if(StartFocused){var r=Owner.Program.Buttons[2].Bounds;using(var pen=new Pen(Color.Gold,2))e.Graphics.DrawRectangle(pen,b.X+r.X*b.Width/640,b.Y+r.Y*b.Height/480,r.Width*b.Width/640,r.Height*b.Height/480);}}
        }
    }
}
